 fn use_a(&mut self,u:&Value)->Result<()>{if !u.is_object(){return Err(er("usage must be object"));}for(k,n)in[("input_tokens","inputTokens"),("cache_read_input_tokens","cacheReadTokens"),("cache_creation_input_tokens","cacheWriteTokens"),("output_tokens","outputTokens")]{if let Some(x)=count(u,k)?{if self.usage[n].as_u64().is_some_and(|old|if n=="outputTokens"{x<old}else{x!=old}){return Err(er("Anthropic usage count changed/decreased"))}self.usage[n]=json!(x);}}Ok(())}
 fn use_o(&mut self,u:&Value)->Result<()>{if !u.is_object(){return Err(er("usage must be object"))}for k in ["prompt_tokens_details","completion_tokens_details"]{if u.get(k).is_some_and(|v|!v.is_null()&&!v.is_object()){return Err(er("usage details must be object"))}}let p=count(u,"prompt_tokens")?;let hit=count(u,"prompt_cache_hit_tokens")?;let cached=count(u.get("prompt_tokens_details").unwrap_or(&Value::Null),"cached_tokens")?;if hit.zip(cached).is_some_and(|(a,b)|a!=b){return Err(er("conflicting cached token counts"))}let h=hit.or(cached);let m=count(u,"prompt_cache_miss_tokens")?;for(k,n)in[("p",p),("h",h),("m",m)]{if let Some(n)=n{if self.ou[k].as_u64().is_some_and(|old|old!=n){return Err(er("input usage count changed during stream"))}self.ou[k]=json!(n);}}let p=self.ou["p"].as_u64();let h=self.ou["h"].as_u64();let m=self.ou["m"].as_u64();if p.zip(h).is_some_and(|(p,h)|h>p)||p.zip(m).is_some_and(|(p,m)|m>p)||p.zip(h.zip(m)).is_some_and(|(p,(h,m))|h.checked_add(m)!=Some(p)){return Err(er("inconsistent prompt/cache token counts"))}let i=m.or_else(||p.map(|p|p-h.unwrap_or(0)));for(k,v)in[("inputTokens",i),("cacheReadTokens",h),("outputTokens",count(u,"completion_tokens")?),("reasoningTokens",count(u.get("completion_tokens_details").unwrap_or(&Value::Null),"reasoning_tokens")?)]{if let Some(v)=v{if ["outputTokens","reasoningTokens"].contains(&k)&&self.usage[k].as_u64().is_some_and(|old|v<old){return Err(er("usage count decreased during stream"))}self.usage[k]=json!(v);}}if let (Some(r),Some(o))=(self.usage["reasoningTokens"].as_u64(),self.usage["outputTokens"].as_u64()){if r>o{return Err(er("reasoning count exceeds output count"))}}Ok(())}
