struct Recovery{sid:String,state:Value,steps:u64,local:u64,call:u64,active:String,generation:u64,ratios:Vec<f64>,last:Value,totals:Value,prices:Vec<Value>,pending:Option<Value>,completed:Vec<Value>,intents:BTreeSet<usize>,request:Option<Value>,ended:bool,stopped:String,error:Value,estimated:u64,halt:bool}
fn fresh(mut state:Value,w:&str,sid:String)->Recovery{if state.get("turns").is_none(){state["turns"]=json!([])}state["currentCap"]=state.get("maxSteps").cloned().unwrap_or(Value::Null);Recovery{sid,state,steps:0,local:0,call:0,active:w.into(),generation:0,ratios:vec![],last:Value::Null,totals:json!({"calls":0,"inputTokens":{"total":0,"missing":0},"cacheReadTokens":{"total":0,"missing":0},"cacheWriteTokens":{"total":0,"missing":0},"outputTokens":{"total":0,"missing":0},"reasoningTokens":{"total":0,"missing":0}}),prices:vec![],pending:None,completed:vec![],intents:BTreeSet::new(),request:None,ended:false,stopped:String::new(),error:Value::Null,estimated:0,halt:false}}
