fn first_catalog(b:&[u8])->Result<String>{let C(v)=serde_json::from_slice(b)?;v.into_iter().next().ok_or_else(||er("model catalog is empty"))}

fn dump_path(root:&Path,dir:&Path)->Result<PathBuf>{if dir.as_os_str().is_empty(){return Err(er("dump-wire path is empty"))}let root=root.canonicalize()?;let dir=if dir.is_absolute(){dir.to_path_buf()}else{std::env::current_dir()?.join(dir)};if dir.components().any(|x|matches!(x,std::path::Component::ParentDir|std::path::Component::CurDir))||dir.starts_with(root){return Err(er("dump-wire must be a normalized path outside workspace"));}Ok(dir)}
#[cfg(test)]mod tests{use super::*;#[test]fn ordered_catalog_and_secure_target(){assert_eq!(first_catalog(br#"{"z":{"models":{"z-first":{},"a-second":{}}},"a":{"models":{"a":{}}}}"#).unwrap(),"z-first");let d=decl(&json!({}),&json!({})).unwrap();assert_eq!(target(&d).unwrap(),"https://api.deepseek.com/anthropic/v1/messages");for h in ["http://api.deepseek.com","https://api.deepseek.com@evil.example","https://api.deepseek.com/path","https://api.deepseek.com:80","https://api.deepseek.com\n"]{let mut q=d.clone();q.host=h.into();assert!(target(&q).is_err());}let mut q=d.clone();q.path="//evil.example".into();assert!(target(&q).is_err());}#[test]fn bounded_receipts_and_unknown_prices(){let x="中".repeat(5000);let r=capped(&x);assert!(r.len()<=8192);assert!(r.contains("bytes omitted"));assert!(r.ends_with("中"));let d=decl(&json!({}),&json!({})).unwrap();let p=price(&d,&json!({"model":"unknown","inputTokens":10})).unwrap();assert!(p["usd"].is_null());assert_eq!(p["missing"],3);assert!(price(&d,&json!({"inputTokens":0,"cacheReadTokens":0,"cacheWriteTokens":0,"outputTokens":0})).unwrap()["usd"].as_f64()==Some(0.0));}}

pub fn catalog(root:&Path)->Result<Value>{let cfg=config::read(root)?;catalog_with_config(root,&cfg)}
pub fn catalog_with_config(_root:&Path,cfg:&Value)->Result<Value>{let p=sys().join("models.json");let mut models=serde_json::Map::new();let mut providers=serde_json::Map::new();let mut prices=vec![];match std::fs::symlink_metadata(&p){Ok(_)=>{let raw=util::json(&util::read_limited(&p,L)?)?;let ps=raw.as_object().ok_or_else(||er("catalog must be an object"))?;for(pid,p)in ps{let ms=p["models"].as_object().ok_or_else(||er("provider models must be object"))?;for(mid,m)in ms{let d=decl(cfg,&json!({"model":mid}))?;let mut m=m.clone();m["id"]=json!(mid);m["provider"]=json!(pid);m["budget"]["trigger"]=json!(d.trigger);models.insert(mid.clone(),m);}let mut provider=json!({"host":p["host"]});for k in ["wireOverrides","retries"]{if let Some(v)=p.get(k){provider[k]=v.clone()}}providers.insert(pid.clone(),provider);prices.extend(p["prices"].as_array().ok_or_else(||er("catalog prices must be array"))?.clone());}},Err(e)if e.kind()==std::io::ErrorKind::NotFound=>{for mid in ["deepseek-flash/anthropic","deepseek-flash/openai"]{let d=decl(cfg,&json!({"model":mid}))?;models.insert(mid.into(),json!({"id":d.id,"provider":d.provider,"wire":d.wire,"model":d.model,"protocol":d.protocol,"systemPromptUpdate":"in-history","contextLimit":d.limit,"budget":{"trigger":d.trigger,"handoffMargin":d.margin},"call":d.call}));if providers.is_empty(){providers.insert(d.provider,json!({"host":d.host,"wireOverrides":{"anthropic-messages":"/anthropic/v1/messages"}}));prices=d.prices;}}},Err(e)=>return Err(e.into())}if models.is_empty(){return Err(er("catalog has no models"))}Ok(json!({"providers":providers,"models":models,"prices":prices,"defaultModel":decl(cfg,&json!({}))?.id}))}
pub fn price_phase()->Result<String>{let sec=SystemTime::now().duration_since(UNIX_EPOCH).map_err(|_|er("clock before epoch"))?.as_secs();let day=(sec/86400+4)%7;let hour=(sec/3600)%24;Ok(if day!=0&&day!=6&&((1..4).contains(&hour)||(6..10).contains(&hour)){"peak"}else{"off-peak"}.into())}
#[cfg(test)]mod recovery_tests{use super::*;#[test]fn configured_retries_share_body_and_never_dispatch_partial_attempts(){let root=tempfile::tempdir().unwrap();let wire=tempfile::tempdir().unwrap();let body=b"{}";let raw=b"data: [DONE]\n\n";let p=wire.path().join("call-0001");std::fs::create_dir(&p).unwrap();std::fs::write(p.join("request.json"),body).unwrap();std::fs::write(p.join("response.sse"),raw).unwrap();std::fs::write(p.join("meta.json"),serde_json::to_vec(&json!({"requestHash":assemble::hash(body),"responseHash":assemble::hash(raw),"attempts":[503,200]})).unwrap()).unwrap();let mut d=decl(&json!({}),&json!({})).unwrap();d.retries=retry(Some(&json!({"count":1,"on":[503],"timeout":false}))).unwrap();let (b,a)=response(root.path(),"agent/a","s","agent/a",&d,None,wire.path().to_str(),1,body).unwrap();assert_eq!(a,[503,200]);assert_eq!(b,raw);let rows=journal::read(root.path(),"agent/a").unwrap();assert_eq!(rows.len(),2);assert!(rows.iter().all(|r|r.event["bodyHash"]==assemble::hash(body)));assert!(!rows.iter().any(|r|r.event["t"]=="tool/receipt"));d.retries=retry(None).unwrap();assert!(response(root.path(),"agent/b","s","agent/b",&d,None,wire.path().to_str(),1,body).is_err());}#[test]fn malformed_retry_configuration_cannot_expand_attempts(){for v in [json!({"count":17,"on":[503],"timeout":true}),json!({"count":1,"on":[99],"timeout":false}),json!({"count":1,"on":[503,503],"timeout":false}),json!({"count":1,"on":[],"timeout":"yes"})]{assert!(retry(Some(&v)).is_err())}}}
#[cfg(test)]mod http_recovery_tests{use super::*;#[test]fn http_interim_frames_and_wire_errors_are_not_transport_timeouts(){assert_eq!(http(b"HTTP/1.1 100 Continue\r\n\r\nHTTP/1.1 200 OK\r\nContent-Type: text/event-stream; charset=utf-8\r\n\r\ndata: ok\n\n").unwrap(),b"data: ok\n\n");assert!(http(b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nanything").is_err());assert!(http(b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Type: text/plain\r\n\r\nanything").is_err());assert!(http(b"HTTP/1.1 503 busy\r\n\r\n").unwrap_err().message.ends_with("HTTP status 503"));}}
#[cfg(test)]mod receipt_tests{use super::*;#[test]fn long_receipt_keeps_diagnostic_and_latest_budget_tail_inside_strict_utf8_cap(){let text=format!("FIRST DIAGNOSTIC\n{}\n(At most 4 steps for this task · this is step 3: 1 left. Land the deliverable now.)","字".repeat(12000));let r=capped(&text);assert!(r.len()<=8192);assert!(r.starts_with("FIRST DIAGNOSTIC"));assert!(r.contains("bytes omitted"));assert!(r.ends_with("Land the deliverable now.)"));assert!(!r.contains('\u{fffd}'));}#[test]fn cap_notice_supersedes_old_limit_without_changing_branch_or_scope_fields(){let s=json!({"runtime":"old opening","goal":"same","task":{"ownedPaths":["src"]}});let n=step_notice(&s,5,1).unwrap();assert!(n.contains("current explicit cap is 5"));assert!(n.contains("supersedes the original limit"));assert!(n.starts_with("old opening"));assert!(step_notice(&s,0,1).is_err());}}
#[cfg(test)]mod transport_hardening_tests{
use super::*;use std::os::unix::fs::OpenOptionsExt;
fn sh(script:&str)->Command{let mut c=Command::new("/bin/sh");c.args(["-c",script]);c}
#[test]fn parent_pumps_large_input_and_output_together_without_worker_threads(){let input=vec![b'x';256*1024];let out=exchange(sh("/bin/cat; printf done"),&input,input.len()+4,Duration::from_secs(3)).unwrap();assert_eq!(&out[..input.len()],input);assert_eq!(&out[input.len()..],b"done");}
#[test]fn transport_environment_core_dumps_and_regular_file_writes_are_disabled(){let mut c=sh("printf '%s\\n' \"${FUGUE_TRANSPORT_TEST_SECRET-empty}\"; ulimit -c; ulimit -f");c.env("FUGUE_TRANSPORT_TEST_SECRET","test-only-secret");let out=exchange(c,b"",1024,Duration::from_secs(3)).unwrap();assert_eq!(out,b"empty\n0\n0\n");let c=transport();assert_eq!(c.get_program(),"/usr/bin/curl");let a=c.get_args().map(|s|s.to_str().unwrap()).collect::<Vec<_>>();assert_eq!(a[0],"--disable");for pair in [["--proto","=https"],["--proto-redir","=https"],["--max-redirs","0"],["--noproxy","*"]]{assert!(a.windows(2).any(|s|s==pair));}assert!(a.contains(&"--globoff"));assert!(!a.iter().any(|s|s.contains("secret")));}
fn running(pid:u32)->bool{std::fs::read_to_string(format!("/proc/{pid}/stat")).ok().is_some_and(|s|s.rsplit_once(") ").is_some_and(|(_,s)|!s.starts_with(['Z','X'])))}
fn linger(script:&str){let d=tempfile::tempdir().unwrap();let path=d.path().join("pids");let name=std::ffi::CString::new(path.as_os_str().as_encoded_bytes()).unwrap();assert_eq!(unsafe{libc::mkfifo(name.as_ptr(),0o600)},0);let mut fifo=std::fs::OpenOptions::new().read(true).write(true).custom_flags(libc::O_NONBLOCK).open(&path).unwrap();let script=script.replace("FIFO",&format!("'{}'",path.display()));let at=Instant::now();let err=exchange(sh(&script),b"",1024,Duration::from_millis(200)).unwrap_err();assert!(err.message.contains("timed out"),"{err:?}");assert!(at.elapsed()<Duration::from_secs(3));let mut b=[0u8;128];let n=fifo.read(&mut b).unwrap();let pids=std::str::from_utf8(&b[..n]).unwrap().split_whitespace().map(|s|s.parse::<u32>().unwrap()).collect::<Vec<_>>();assert_eq!(pids.len(),2);assert!(!running(pids[0]),"transport leader remained live");let until=Instant::now()+Duration::from_secs(1);while running(pids[1])&&Instant::now()<until{std::thread::sleep(Duration::from_millis(10));}assert!(!running(pids[1]),"transport descendant remained live");}
#[test]fn parent_deadline_kills_and_reaps_a_child_that_never_finishes(){linger("/bin/sleep 30 & printf '%s %s\\n' \"$$\" \"$!\" > FIFO; wait");}
#[test]fn inherited_stdout_cannot_hold_a_finished_transport_open(){linger("/bin/sleep 30 & printf '%s %s\\n' \"$$\" \"$!\" > FIFO; exit 0");}
#[test]fn pipe_eof_does_not_erase_an_unfinished_child_deadline(){let at=Instant::now();assert!(exchange(sh("exec 1>&-; /bin/sleep 30"),b"",16,Duration::from_millis(100)).unwrap_err().message.contains("timed out"));assert!(at.elapsed()<Duration::from_secs(3));}
#[test]fn output_overflow_and_early_input_close_fail_closed(){let e=exchange(sh("while :; do printf abcdefghijklmnopqrstuvwxyz; done"),b"",1024,Duration::from_secs(3)).unwrap_err();assert!(e.message.contains("byte limit"));assert!(exchange(sh("exit 0"),&vec![b'x';1024*1024],16,Duration::from_secs(3)).is_err());assert!(exchange(sh("exit 28"),b"",16,Duration::from_secs(3)).unwrap_err().message.contains("timed out"));assert!(!exchange(sh("exit 7"),b"",16,Duration::from_secs(3)).unwrap_err().message.contains("timed out"));}
#[test]fn malformed_http_status_headers_and_ambiguous_framing_are_rejected(){for h in ["garbage 200 OK\r\nContent-Type: text/event-stream","HTTP/1.1 +200 OK\r\nContent-Type: text/event-stream","HTTP/1.1 200 OK\r\nContent-Type : text/event-stream","HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\nInjected: yes","HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nmalformed","HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: 3\r\nTransfer-Encoding: chunked","HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: 3\r\nContent-Length: 3"]{assert!(http(format!("{h}\r\n\r\ndata: ok\n\n").as_bytes()).is_err(),"{h:?}")}for proto in ["HTTP/1.0","HTTP/1.1","HTTP/2","HTTP/3"]{assert_eq!(http(format!("{proto} 200 OK\r\ncontent-type: text/event-stream\r\n\r\ndata: ok\n\n").as_bytes()).unwrap(),b"data: ok\n\n");}}
}
#[cfg(test)]mod evidence_hardening_tests{use super::*;
#[test]fn partial_dump_evidence_is_never_overwritten_even_without_metadata(){let root=tempfile::tempdir().unwrap();let d=decl(&json!({}),&json!({})).unwrap();let prefix=Prefix{a:"a".into(),b:"b".into(),c:"c".into()};for leaf in ["request.json","response.sse","meta.json","unexpected"]{let dir=tempfile::tempdir().unwrap();let at=dir.path().join("call-0001");std::fs::create_dir(&at).unwrap();std::fs::write(at.join(leaf),b"immutable prior evidence").unwrap();assert!(dump(root.path(),dir.path(),1,&d,&prefix,b"new request",b"new response",None,None).is_err());assert_eq!(std::fs::read(at.join(leaf)).unwrap(),b"immutable prior evidence");assert_eq!(std::fs::read_dir(&at).unwrap().count(),1);}let dir=tempfile::tempdir().unwrap();let at=dir.path().join("call-0001");std::fs::create_dir(&at).unwrap();std::os::unix::fs::symlink("missing-metadata",at.join("meta.json")).unwrap();assert!(dump(root.path(),dir.path(),1,&d,&prefix,b"new",b"new",None,None).is_err());assert_eq!(std::fs::read_link(at.join("meta.json")).unwrap(),Path::new("missing-metadata"));assert_eq!(std::fs::read_dir(&at).unwrap().count(),1);}
#[test]fn successful_dump_is_private_complete_immutable_and_replayable(){use std::os::unix::fs::PermissionsExt;let root=tempfile::tempdir().unwrap();let dir=tempfile::tempdir().unwrap();let d=decl(&json!({}),&json!({})).unwrap();let p=Prefix{a:"a".into(),b:"b".into(),c:"c".into()};dump(root.path(),dir.path(),1,&d,&p,b"{}",b"offline SSE",None,Some("offline fixture")).unwrap();let at=dir.path().join("call-0001");assert_eq!(std::fs::metadata(&at).unwrap().permissions().mode()&0o777,0o700);for leaf in ["request.json","response.sse","meta.json","request.sha256","response.sha256"]{assert_eq!(std::fs::metadata(at.join(leaf)).unwrap().permissions().mode()&0o777,0o600);}assert_eq!(replay(dir.path(),1,b"{}").unwrap(),b"offline SSE");assert!(dump(root.path(),dir.path(),1,&d,&p,b"changed",b"changed",None,None).is_err());assert_eq!(replay(dir.path(),1,b"{}").unwrap(),b"offline SSE");}
#[test]fn dangling_full_checksum_marker_cannot_silently_disable_integrity_check(){let dir=tempfile::tempdir().unwrap();let at=dir.path().join("call-0001");std::fs::create_dir(&at).unwrap();std::fs::write(at.join("request.json"),b"{}").unwrap();std::fs::write(at.join("response.sse"),b"offline").unwrap();std::fs::write(at.join("meta.json"),serde_json::to_vec(&json!({"requestHash":assemble::hash(b"{}")})).unwrap()).unwrap();std::os::unix::fs::symlink("missing-checksum",at.join("response.sha256")).unwrap();assert!(replay(dir.path(),1,b"{}").is_err());assert!(replay(dir.path(),0,b"{}").is_err());}
}
